#!/bin/bash
# Run an eidchain node on macOS behind a Cloudflare Tunnel.
#
#   deploy/macos/install.sh render DIR          write every generated file to DIR (review, test)
#   sudo deploy/macos/install.sh install [--seed DATA-DIR]
#   sudo deploy/macos/install.sh uninstall      stop the services; data and keys stay
#
# Why this shape: the node has no limits of its own (README, Deployment), so it
# must not face the internet directly. cloudflared makes an outbound connection
# to Cloudflare, which terminates TLS, so no router port is opened. nginx sits
# between the tunnel and the node with the same write limits, body caps and
# headers as deploy/nginx-eidchain.conf. Each piece is a LaunchDaemon running as
# an unprivileged service user.
#
# Settings come from deploy/macos/eidchain.env (see eidchain.env.example).
# Build first, as yourself: go build -o bin/eidchain ./cmd/eidchain and
# deploy/macos/build-nginx.sh (bin/nginx).
# --seed copies a chain (genesis, config.json, keys) into the data directory on
# the first install; later installs never touch the data.
set -euo pipefail
cd "$(dirname "$0")/../.."
REPO=$PWD

ENV_FILE=${EIDCHAIN_ENV:-deploy/macos/eidchain.env}
[[ -f "$ENV_FILE" ]] || { echo "missing $ENV_FILE: copy deploy/macos/eidchain.env.example" >&2; exit 1; }
# shellcheck source=/dev/null
. "$ENV_FILE"

log() { echo "== $*"; }
die() { echo "error: $*" >&2; exit 1; }
label() { echo "$LABEL_PREFIX.$1"; }
xml_escape() { sed -e 's/&/\&amp;/g' -e 's/</\&lt;/g' -e 's/>/\&gt;/g' <<<"$1"; }

services() {
  echo node nginx
  [[ -n "${TUNNEL_ID:-}" ]] && echo tunnel
  return 0
}

# write_plist FILE NAME WORKDIR -- ARGS...
write_plist() {
  local file=$1 name=$2 workdir=$3 a
  shift 4
  {
    cat <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<!-- Generated by eidchain deploy/macos/install.sh. Do not edit; change eidchain.env and re-run. -->
<plist version="1.0">
<dict>
  <key>Label</key><string>$(label "$name")</string>
  <key>UserName</key><string>$SERVICE_USER</string>
  <key>GroupName</key><string>$SERVICE_USER</string>
  <key>ProgramArguments</key>
  <array>
EOF
    for a in "$@"; do printf '    <string>%s</string>\n' "$(xml_escape "$a")"; done
    cat <<EOF
  </array>
  <key>WorkingDirectory</key><string>$workdir</string>
  <key>RunAtLoad</key><true/>
  <key>KeepAlive</key><true/>
  <key>ThrottleInterval</key><integer>10</integer>
  <key>ExitTimeOut</key><integer>15</integer>
  <key>ProcessType</key><string>Standard</string>
  <key>StandardOutPath</key><string>/dev/null</string>
  <key>StandardErrorPath</key><string>$PREFIX/logs/$name.stderr.log</string>
</dict>
</plist>
EOF
  } >"$file"
}

render_nginx() {
  cat <<EOF
# Generated by eidchain deploy/macos/install.sh. Do not edit; change eidchain.env and re-run.
# Behind cloudflared, so plain HTTP on loopback. The locations follow
# deploy/nginx-eidchain.conf, without /login/: TLS ends at Cloudflare, so a
# client certificate never reaches this server.
daemon off;
worker_processes 1;
pid $PREFIX/state/nginx/nginx.pid;
error_log $PREFIX/logs/nginx.error.log warn;
events { worker_connections 256; }

http {
    include $PREFIX/etc/mime.types;
    default_type application/octet-stream;
    access_log off;                  # no client addresses on success paths
    server_tokens off;
    client_body_temp_path $PREFIX/state/nginx/body;
    proxy_temp_path $PREFIX/state/nginx/proxy;
    fastcgi_temp_path $PREFIX/state/nginx/fastcgi;
    uwsgi_temp_path $PREFIX/state/nginx/uwsgi;
    scgi_temp_path $PREFIX/state/nginx/scgi;

    # Every request comes from cloudflared on loopback. Without this the write
    # limit below would be one bucket shared by the whole internet.
    set_real_ip_from 127.0.0.1;
    real_ip_header CF-Connecting-IP;

    map \$request_method \$eidchain_write_key {
        POST    \$binary_remote_addr;
        default "";
    }
    limit_req_zone \$eidchain_write_key zone=eidchain_write:10m rate=30r/m;

    server {
        listen 127.0.0.1:$NGINX_PORT;
        server_name $DOMAIN ${ALIASES:-};
        root $PREFIX/www;
        index index.html;

        location / {
            add_header Content-Security-Policy "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" always;
            add_header Strict-Transport-Security "max-age=31536000" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Referrer-Policy "no-referrer" always;
            add_header Cache-Control "no-cache" always;
            try_files \$uri \$uri/ =404;
        }

        location /signer/ {
            add_header Content-Security-Policy "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'none'; img-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'" always;
            add_header Strict-Transport-Security "max-age=31536000" always;
            add_header X-Content-Type-Options "nosniff" always;
            add_header Referrer-Policy "no-referrer" always;
            add_header Cache-Control "no-cache" always;
            try_files \$uri \$uri/ =404;
        }

        location = /chain {
            return 301 /chain/;
        }

        location = /chain/api/v1/blocks {
            client_max_body_size 9m;
            limit_req zone=eidchain_write burst=30 nodelay;
            limit_req_status 429;
            proxy_pass http://127.0.0.1:$NODE_PORT/api/v1/blocks;
            proxy_set_header Host \$host;
            proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto https;
            add_header Strict-Transport-Security "max-age=31536000" always;
        }

        location /chain/ {
            client_max_body_size 300k;
            limit_req zone=eidchain_write burst=30 nodelay;
            limit_req_status 429;
            proxy_pass http://127.0.0.1:$NODE_PORT/;
            proxy_set_header Host \$host;
            proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto https;
            proxy_read_timeout 90s;      # payload submission waits for the OCSP responder
            add_header Strict-Transport-Security "max-age=31536000" always;
        }
    }
}
EOF
}

render_tunnel() {
  cat <<EOF
# Generated by eidchain deploy/macos/install.sh. Do not edit; change eidchain.env and re-run.
tunnel: $TUNNEL_ID
credentials-file: $PREFIX/secrets/cloudflared/$TUNNEL_ID.json
ingress:
EOF
  local h
  for h in $DOMAIN ${ALIASES:-}; do
    printf '  - hostname: %s\n    service: http://127.0.0.1:%s\n' "$h" "$NGINX_PORT"
  done
  echo "  - service: http_status:404"
}

# render_www DIR: the site without the card-login page, which cannot work here.
render_www() {
  local dir=$1
  mkdir -p "$dir"
  rsync -a --delete --exclude login/ "$REPO/www/" "$dir/"
  sed -i '' -e "s|<p class=\"eyebrow\">eidchain.ivoras.net</p>|<p class=\"eyebrow\">$DOMAIN</p>|" \
    -e '/href="\/login\/"/d' "$dir/index.html"
}

# render_all ROOT PLISTDIR: configs under ROOT (laid out like PREFIX), plists in PLISTDIR.
render_all() {
  local root=$1 plists=$2 peers=() p
  mkdir -p "$root/etc" "$plists"
  render_nginx >"$root/etc/nginx.conf"
  cp "$REPO/bin/nginx.mime.types" "$root/etc/mime.types"
  [[ -n "${TUNNEL_ID:-}" ]] && render_tunnel >"$root/etc/cloudflared.yml"
  render_www "$root/www"
  for p in ${PEERS:-}; do peers+=(--peer "$p"); done
  write_plist "$plists/$(label node).plist" node "$PREFIX/data" -- \
    "$PREFIX/bin/eidchain" node --data "$PREFIX/data" --listen "127.0.0.1:$NODE_PORT" \
    --advertise "https://$DOMAIN/chain" ${peers[@]+"${peers[@]}"}
  write_plist "$plists/$(label nginx).plist" nginx "$PREFIX/state/nginx" -- \
    "$PREFIX/bin/nginx" -p "$PREFIX/state/nginx" -e "$PREFIX/logs/nginx.error.log" -c "$PREFIX/etc/nginx.conf"
  if [[ -n "${TUNNEL_ID:-}" ]]; then
    write_plist "$plists/$(label tunnel).plist" tunnel "$PREFIX/state" -- \
      "$CLOUDFLARED" tunnel --no-autoupdate --config "$PREFIX/etc/cloudflared.yml" --metrics "$TUNNEL_METRICS" run
  fi
}

create_user() {
  if ! dscl . -read "/Groups/$SERVICE_USER" >/dev/null 2>&1; then
    dscl . -list /Groups PrimaryGroupID | awk -v g="$SERVICE_UID" '$2==g {f=1} END {exit !f}' && die "gid $SERVICE_UID is taken"
    dscl . -create "/Groups/$SERVICE_USER"
    dscl . -create "/Groups/$SERVICE_USER" PrimaryGroupID "$SERVICE_UID"
    dscl . -create "/Groups/$SERVICE_USER" RealName "eidchain node"
    dscl . -create "/Groups/$SERVICE_USER" Password '*'
  fi
  if ! dscl . -read "/Users/$SERVICE_USER" >/dev/null 2>&1; then
    dscl . -list /Users UniqueID | awk -v u="$SERVICE_UID" '$2==u {f=1} END {exit !f}' && die "uid $SERVICE_UID is taken"
    dscl . -create "/Users/$SERVICE_USER"
    dscl . -create "/Users/$SERVICE_USER" UniqueID "$SERVICE_UID"
    dscl . -create "/Users/$SERVICE_USER" PrimaryGroupID "$SERVICE_UID"
    dscl . -create "/Users/$SERVICE_USER" UserShell /usr/bin/false
    dscl . -create "/Users/$SERVICE_USER" NFSHomeDirectory /var/empty
    dscl . -create "/Users/$SERVICE_USER" RealName "eidchain node"
    dscl . -create "/Users/$SERVICE_USER" IsHidden 1
    dscl . -create "/Users/$SERVICE_USER" Password '*'
    echo "   user $SERVICE_USER created (no shell, no password, hidden)"
  fi
}

stop() {
  local s
  for s in tunnel nginx node; do
    launchctl bootout "system/$(label "$s")" 2>/dev/null || true
  done
}

cmd_install() {
  local seed=""
  if [[ "${1:-}" == "--seed" ]]; then seed=${2:?--seed needs a directory}; fi
  [[ $EUID -eq 0 ]] || die "run with sudo"
  [[ -x bin/eidchain ]] || die "build first: go build -o bin/eidchain ./cmd/eidchain"
  [[ -x bin/nginx ]] || die "build nginx first: deploy/macos/build-nginx.sh"
  if [[ -n "${TUNNEL_ID:-}" ]]; then
    [[ -x "$CLOUDFLARED" ]] || die "no cloudflared at $CLOUDFLARED"
    [[ -f "$PREFIX/secrets/cloudflared/$TUNNEL_ID.json" ]] ||
      die "move the tunnel credentials to $PREFIX/secrets/cloudflared/$TUNNEL_ID.json first"
  fi

  log "service user"
  create_user

  log "directories"
  mkdir -p "$PREFIX"/{bin,etc,logs,state/nginx,secrets/cloudflared}
  if [[ ! -f "$PREFIX/data/genesis.json" ]]; then
    [[ -n "$seed" ]] || die "no chain in $PREFIX/data: pass --seed DIR with genesis.json, config.json and keys/"
    [[ -f "$seed/genesis.json" ]] || die "$seed has no genesis.json"
    mkdir -p "$PREFIX/data"
    rsync -a "$seed/" "$PREFIX/data/"
    echo "   seeded $PREFIX/data from $seed"
  fi
  install -m 755 bin/eidchain "$PREFIX/bin/eidchain"
  install -m 755 bin/nginx "$PREFIX/bin/nginx"

  log "configuration"
  local tmp
  tmp=$(mktemp -d)
  render_all "$PREFIX" "$tmp"
  # Refuse a config nginx would not start with, before anything is stopped.
  "$PREFIX/bin/nginx" -t -p "$PREFIX/state/nginx" -e "$PREFIX/logs/nginx.error.log" -c "$PREFIX/etc/nginx.conf"

  chown -R root:wheel "$PREFIX/bin" "$PREFIX/etc" "$PREFIX/www"
  chown -R "$SERVICE_USER:$SERVICE_USER" "$PREFIX/data" "$PREFIX/logs" "$PREFIX/state" "$PREFIX/secrets"
  chmod 700 "$PREFIX/data" "$PREFIX/secrets" "$PREFIX/secrets/cloudflared"
  [[ -d "$PREFIX/data/keys" ]] && chmod 700 "$PREFIX/data/keys" && chmod 600 "$PREFIX"/data/keys/*.key 2>/dev/null
  find "$PREFIX/secrets" -type f -exec chmod 600 {} +

  log "launch daemons"
  stop
  rm -f /Library/LaunchDaemons/"$LABEL_PREFIX".*.plist
  local s
  for s in $(services); do
    install -m 644 -o root -g wheel "$tmp/$(label "$s").plist" /Library/LaunchDaemons/
    launchctl bootstrap system "/Library/LaunchDaemons/$(label "$s").plist"
    echo "   $(label "$s") started"
  done
  rm -rf "$tmp"
  echo "logs: $PREFIX/logs/*.stderr.log"
}

cmd_uninstall() {
  [[ $EUID -eq 0 ]] || die "run with sudo"
  stop
  rm -f /Library/LaunchDaemons/"$LABEL_PREFIX".*.plist
  echo "services removed; $PREFIX (chain, keys, tunnel credentials) is left in place"
}

case "${1:-}" in
  render)
    dir=${2:?usage: install.sh render DIR}
    render_all "$dir" "$dir/LaunchDaemons"
    echo "rendered into $dir"
    ;;
  install) shift; cmd_install "$@" ;;
  uninstall) cmd_uninstall ;;
  *) sed -n '2,6p' "$0" >&2; exit 2 ;;
esac
